6	
7	const messages = {
8	    emailNotFound: 'Email not found.',
9	    retryNotAllowed: 'Only failed emails can be retried'
10	};
11	
12	const allowedBatchIncludes = ['count.recipients'];
13	const allowedFailureIncludes = ['member', 'email_recipient'];
14	
15	/** @type {import('@tryghost/api-framework').Controller} */
16	const controller = {
17	    docName: 'emails',
18	
19	    browse: {
20	        headers: {
21	            cacheInvalidate: false
22	        },
23	        options: [
24	            'limit',
25	            'fields',
26	            'filter',
27	            'order',
28	            'page'
29	        ],
30	        permissions: true,
31	        async query(frame) {
32	            return await models.Email.findPage(frame.options);
33	        }
34	    },
35	
36	    read: {
37	        headers: {
38	            cacheInvalidate: false
39	        },
40	        options: [
41	            'fields'
42	        ],
43	        validation: {
44	            options: {
45	                fields: ['html', 'plaintext', 'subject']
46	            }
47	        },
48	        data: [
49	            'id'
50	        ],
51	        permissions: true,
52	        async query(frame) {
53	            const model = await models.Email.findOne(frame.data, frame.options);
54	            if (!model) {
55	                throw new errors.NotFoundError({
56	                    message: tpl(messages.emailNotFound)
57	                });
58	            }
59	
60	            return model;
61	        }
62	    },
63	
64	    retry: {
65	        headers: {
66	            cacheInvalidate: false
67	        },
68	        data: [
69	            'id'
70	        ],
71	        permissions: true,
72	        async query(frame) {
73	            return await emailService.controller.retryFailedEmail(frame);
74	        }
75	    },
76	
77	    browseBatches: {
78	        headers: {
79	            cacheInvalidate: false
80	        },
81	        options: [
82	            'limit',
83	            'fields',
84	            'filter',
85	            'order',
86	            'page',
87	            'include'
88	        ],
89	        data: [
90	            'id'
91	        ],
92	        validation: {
93	            options: {
94	                include: {
95	                    values: allowedBatchIncludes
96	                }
97	            }
98	        },
99	        permissions: {
100	            method: 'browse'
101	        },
102	        async query(frame) {
103	            const filter = `email_id:'${frame.data.id}'` + (frame.options.filter ? `+(${frame.options.filter})` : '');
