106	    },
107	
108	    browseFailures: {
109	        headers: {
110	            cacheInvalidate: false
111	        },
112	        options: [
113	            'limit',
114	            'fields',
115	            'filter',
116	            'order',
117	            'page',
118	            'include'
119	        ],
120	        data: [
121	            'id'
122	        ],
123	        validation: {
124	            options: {
125	                include: {
126	                    values: allowedFailureIncludes
127	                }
128	            }
129	        },
130	        permissions: {
131	            method: 'browse'
132	        },
133	        async query(frame) {
134	            const filter = `email_id:'${frame.data.id}'` + (frame.options.filter ? `+(${frame.options.filter})` : '');
135	            return await models.EmailRecipientFailure.findPage({...frame.options, filter});
136	        }
137	    },
138	
139	    analyticsStatus: {
140	        headers: {
141	            cacheInvalidate: false
142	        },
143	        permissions: {
144	            method: 'browse'
145	        },
146	        async query() {
147	            return emailAnalytics.service.getStatus();
148	        }
149	    },
150	
151	    scheduleAnalytics: {
152	        headers: {
153	            cacheInvalidate: false
154	        },
155	        permissions: {
156	            method: 'browse'
157	        },
158	        data: [
159	            'id'
160	        ],
161	        async query(frame) {
162	            const model = await models.Email.findOne(frame.data, frame.options);
163	            return emailAnalytics.service.schedule({
164	                begin: model.get('created_at'),
165	                end: new Date(Math.min(Date.now() - 60 * 60 * 1000, model.get('created_at').getTime() + 24 * 60 * 60 * 1000 * 7))
166	            });
167	        }
168	    },
169	
170	    cancelScheduledAnalytics: {
171	        headers: {
172	            cacheInvalidate: false
173	        },
174	        permissions: {
175	            method: 'browse'
176	        },
177	        async query() {
178	            return emailAnalytics.service.cancelScheduled();
179	        }
180	    }
181	};
182	
183	module.exports = controller;
