3	const Action = ghostBookshelf.Model.extend({
4	    tableName: 'actions',
5	
6	    candidates() {
7	        return Object.keys(ghostBookshelf.registry.models).map((key) => {
8	            const model = ghostBookshelf.registry.models[key];
9	            return [model, model.prototype.tableName.replace(/s$/, '')];
10	        });
11	    },
12	
13	    actor() {
14	        return this.morphTo('actor', ['actor_type', 'actor_id'], ...this.candidates());
15	    },
16	
17	    resource() {
18	        return this.morphTo('resource', ['resource_type', 'resource_id'], ...this.candidates());
19	    }
20	}, {
21	    orderDefaultOptions: function orderDefaultOptions() {
22	        return {
23	            created_at: 'DESC'
24	        };
25	    },
26	
27	    add(data, unfilteredOptions = {}) {
28	        const options = this.filterOptions(unfilteredOptions, 'add');
29	        return ghostBookshelf.Model.add.call(this, data, options);
30	    }
31	});
32	
33	module.exports = {
34	    Action: ghostBookshelf.model('Action', Action)
35	};
