1	const omit = require('lodash/omit');
2	const security = require('@tryghost/security');
3	const ghostBookshelf = require('./base');
4	const {Role} = require('./role');
5	
6	const ApiKey = ghostBookshelf.Model.extend({
7	    tableName: 'api_keys',
8	
9	    actionsCollectCRUD: true,
10	    actionsResourceType: 'api_key',
11	
12	    defaults() {
13	        const secret = security.secret.create(this.get('type'));
14	
15	        return {
16	            secret
17	        };
18	    },
19	
20	    role() {
21	        return this.belongsTo('Role');
22	    },
23	
24	    integration() {
25	        return this.belongsTo('Integration');
26	    },
27	
28	    user() {
29	        return this.belongsTo('User');
30	    },
31	
32	    format(attrs) {
33	        return omit(attrs, 'role');
34	    },
35	
36	    onSaving(model, attrs, options) {
37	        ghostBookshelf.Model.prototype.onSaving.apply(this, arguments);
38	
39	        // enforce roles which are currently hardcoded
40	        // - admin key = Adminstrator role
41	        // - content key = no role
42	        if (this.hasChanged('type') || this.hasChanged('role_id')) {
43	            if (this.get('type') === 'admin') {
44	                return Role.findOne({name: attrs.role || 'Admin Integration'}, Object.assign({}, options, {columns: ['id']}))
45	                    .then((role) => {
46	                        this.set('role_id', role.get('id'));
47	                    });
48	            }
49	
50	            if (this.get('type') === 'content') {
51	                this.set('role_id', null);
52	            }
53	        }
54	    },
55	    onUpdated(model, options) {
56	        if (this.previous('secret') !== this.get('secret')) {
57	            this.addAction(model, 'refreshed', options);
58	        }
59	    }
60	}, {
61	    refreshSecret(data, options) {
62	        const secret = security.secret.create(data.type);
63	        return this.edit(Object.assign({}, data, {secret}), options);
64	    }
65	});
66	
67	const ApiKeys = ghostBookshelf.Collection.extend({
68	    model: ApiKey
69	});
70	
71	module.exports = {
72	    ApiKey: ghostBookshelf.model('ApiKey', ApiKey),
73	    ApiKeys: ghostBookshelf.collection('ApiKeys', ApiKeys)
74	};
75	

