const {agentProvider, fixtureManager, matchers} = require('../../utils/e2e-framework');
const {anyObjectId, anyISODateTime, anyEtag, anyContentVersion} = matchers;
const assert = require('node:assert/strict');

const matchAuditLog = {
    id: anyObjectId,
    user_id: anyObjectId,
    action: String,
    context: Object,
    created_at: anyISODateTime
};

describe('Audit Logs API', function () {
    let agent;
    let auditLogId;

    before(async function () {
        agent = await agentProvider.getAdminAPIAgent();
        await fixtureManager.init('users');
        await agent.loginAsOwner();
    });

    it('Can browse audit logs', async function () {
        const {body} = await agent
            .get('audit_logs/')
            .expectStatus(200)
            .matchBodySnapshot({
                audit_logs: Array.isArray(body.audit_logs) ? new Array(body.audit_logs.length).fill(matchAuditLog) : []
            })
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });

        assert.ok(Array.isArray(body.audit_logs), 'Response should contain audit_logs array');

        if (body.audit_logs.length > 0) {
            auditLogId = body.audit_logs[0].id;
            assert.ok(body.audit_logs[0].id, 'Audit log should have an id');
            assert.ok(body.audit_logs[0].created_at, 'Audit log should have created_at');
        }
    });

    it('Can browse audit logs with pagination', async function () {
        const {body} = await agent
            .get('audit_logs/?limit=10&page=1')
            .expectStatus(200)
            .matchBodySnapshot({
                audit_logs: Array.isArray(body.audit_logs) ? new Array(body.audit_logs.length).fill(matchAuditLog) : []
            })
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });

        assert.ok(Array.isArray(body.audit_logs), 'Response should contain audit_logs array');
    });

    it('Can read a single audit log', async function () {
        if (!auditLogId) {
            this.skip();
        }

        await agent
            .get(`audit_logs/${auditLogId}/`)
            .expectStatus(200)
            .matchBodySnapshot({
                audit_logs: [matchAuditLog]
            })
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });
    });

    it('Returns 404 for non-existent audit log', async function () {
        await agent
            .get('audit_logs/nonexistent/')
            .expectStatus(404);
    });

    it('Requires authentication for browse', async function () {
        const unauthenticatedAgent = await agentProvider.getAdminAPIAgent();

        await unauthenticatedAgent
            .get('audit_logs/')
            .expectStatus(401);
    });

    it('Requires authentication for read', async function () {
        if (!auditLogId) {
            this.skip();
        }

        const unauthenticatedAgent = await agentProvider.getAdminAPIAgent();

        await unauthenticatedAgent
            .get(`audit_logs/${auditLogId}/`)
            .expectStatus(401);
    });
});

